FString PoseSearchUtils::DiscoverChannels(const FString& Search,int32 Limit)
{
 if(!IsInGameThread() || Search.Len()>128 || Limit<1 || Limit>128) throw std::runtime_error("Channel discovery requires bounded search and limit 1..128"); TArray<UClass*> Classes; for(TObjectIterator<UClass> It;It;++It) if(It->IsChildOf(UPoseSearchFeatureChannel::StaticClass()) && !It->HasAnyClassFlags(CLASS_Abstract|CLASS_Deprecated|CLASS_NewerVersionExists) && It->GetOutermost()->GetName().StartsWith(TEXT("/Script/")) && (Search.IsEmpty() || It->GetPathName().Contains(Search))) Classes.Add(*It); Classes.Sort([](const UClass& A,const UClass& B) { return A.GetPathName()<B.GetPathName(); }); FString Result; auto J=TJsonWriterFactory<>::Create(&Result); J->WriteObjectStart(); J->WriteValue(TEXT("match_count"),Classes.Num()); J->WriteValue(TEXT("truncated"),Classes.Num()>Limit); J->WriteArrayStart(TEXT("channel_types")); for(int32 Index=0;Index<FMath::Min(Classes.Num(),Limit);++Index) { auto* Class=Classes[Index]; auto* Defaults=Class->GetDefaultObject(); J->WriteObjectStart(); J->WriteValue(TEXT("class_path"),Class->GetPathName()); J->WriteValue(TEXT("display_name"),Class->GetDisplayNameText().ToString()); J->WriteArrayStart(TEXT("editable_fields")); int32 Fields=0; for(TFieldIterator<FProperty> It(Class);It;++It) if(It->HasAnyPropertyFlags(CPF_Edit) && !It->HasAnyPropertyFlags(CPF_Transient|CPF_Deprecated)) { if(Fields++>=64) continue; FString Value; It->ExportTextItem_Direct(Value,It->ContainerPtrToValuePtr<void>(Defaults),nullptr,Defaults,PPF_None); J->WriteObjectStart(); J->WriteValue(TEXT("name"),It->GetName()); J->WriteValue(TEXT("type"),It->GetCPPType()); J->WriteValue(TEXT("edit_const"),It->HasAnyPropertyFlags(CPF_EditConst)); const auto* EnumProperty=CastField<FEnumProperty>(*It); const auto* ByteProperty=CastField<FByteProperty>(*It); const UEnum* Enum=EnumProperty?EnumProperty->GetEnum():(ByteProperty?ByteProperty->Enum.Get():nullptr);
 if(Enum) { J->WriteValue(TEXT("enum_path"),Enum->GetPathName()); J->WriteArrayStart(TEXT("enum_choices")); int32 Choices=0;
 for(int32 E=0;E<Enum->NumEnums();++E) { if(Enum->HasMetaData(TEXT("Hidden"),E) || Enum->GetNameStringByIndex(E).EndsWith(TEXT("_MAX"))) continue; ++Choices; if(Choices>128) continue; J->WriteObjectStart(); J->WriteValue(TEXT("name"),Enum->GetNameStringByIndex(E)); J->WriteValue(TEXT("qualified_name"),Enum->GetNameByIndex(E).ToString()); J->WriteValue(TEXT("value_text"),LexToString(Enum->GetValueByIndex(E))); J->WriteValue(TEXT("display_name"),Enum->GetDisplayNameTextByIndex(E).ToString()); J->WriteObjectEnd(); }
 J->WriteArrayEnd(); J->WriteValue(TEXT("enum_choice_count"),Choices); J->WriteValue(TEXT("enum_choices_truncated"),Choices>128); }
  J->WriteValue(TEXT("default"),Value.Left(2048)); J->WriteValue(TEXT("value_truncated"),Value.Len()>2048); for(const FName Key:{FName(TEXT("ClampMin")),FName(TEXT("ClampMax")),FName(TEXT("EditCondition"))}) if(It->HasMetaData(Key)) J->WriteValue(Key.ToString(),It->GetMetaData(Key)); J->WriteObjectEnd(); } J->WriteArrayEnd(); J->WriteValue(TEXT("field_count"),Fields); J->WriteValue(TEXT("fields_truncated"),Fields>64); J->WriteObjectEnd(); } J->WriteArrayEnd(); J->WriteValue(TEXT("scope"),TEXT("Loaded concrete native feature-channel class/default discovery only; native schema finalization determines validity. No channel creation, index build or search. Native exporter intermediate allocation uncapped.")); J->WriteObjectEnd(); J->Close(); return Result;
}

FString PoseSearchUtils::SetSampleRate(const FPoseSearchReq& R)
{
 if(!IsInGameThread() || !GEditor || GEditor->PlayWorld || !R.bConfirm || R.AssetPath.Len()>1024 || !R.AssetPath.StartsWith(TEXT("/Game/")) || R.AssetPath.Contains(TEXT(":")) || !FPackageName::IsValidObjectPath(R.AssetPath) || R.SampleRate<1 || R.SampleRate>240) throw std::runtime_error("Sample rate edit requires stopped PIE, confirmed /Game schema and 1..240 rate"); if(!FModuleManager::LoadModuleChecked<FAssetRegistryModule>(TEXT("AssetRegistry")).Get().GetAssetByObjectPath(FSoftObjectPath(R.AssetPath)).IsValid()) throw std::runtime_error("Schema must exist in registry"); auto* Schema=LoadObject<UPoseSearchSchema>(nullptr,*R.AssetPath); if(!IsValid(Schema) || Schema->HasAnyFlags(RF_Transient)) throw std::runtime_error("Persistent native schema required"); const int32 Before=Schema->SampleRate; const bool Changed=Before!=R.SampleRate; bool Saved=false;
 if(!R.bDryRun && Changed) { auto* Property=FindFProperty<FProperty>(Schema->GetClass(),TEXT("SampleRate")); if(!Property) throw std::runtime_error("Native sample rate property unavailable"); FScopedTransaction Transaction(FText::FromString(TEXT("MCP Pose Search Sample Rate"))); Schema->Modify(); Schema->SampleRate=R.SampleRate; FPropertyChangedEvent Event(Property,EPropertyChangeType::ValueSet); Schema->PostEditChangeProperty(Event); Schema->MarkPackageDirty(); }
 if(!R.bDryRun && R.bSave) { Saved=GEditor->GetEditorSubsystem<UEditorAssetSubsystem>()->SaveLoadedAsset(Schema,false); if(!Saved) throw std::runtime_error("Sample rate edited but schema save failed"); } FString Result; auto J=TJsonWriterFactory<>::Create(&Result); J->WriteObjectStart(); J->WriteValue(TEXT("asset_path"),R.AssetPath); J->WriteValue(TEXT("before"),Before); J->WriteValue(TEXT("requested"),R.SampleRate); J->WriteValue(TEXT("current"),Schema->SampleRate); J->WriteValue(TEXT("would_change"),Changed); J->WriteValue(TEXT("dry_run"),R.bDryRun); J->WriteValue(TEXT("saved"),Saved); J->WriteValue(TEXT("scope"),TEXT("Native schema property edit invokes schema Finalize through PostEditChangeProperty. Referencing database indexes may become stale or react to native notifications; no explicit index build/search requested.")); J->WriteObjectEnd(); J->Close(); return Result;
}

FString PoseSearchUtils::SetDatabaseSchema(const FPoseSearchReq& R)
{
 if(!IsInGameThread() || !GEditor || GEditor->PlayWorld || !R.bConfirm || R.AssetPath.Len()>1024 || !R.AssetPath.StartsWith(TEXT("/Game/")) || R.AssetPath.Contains(TEXT(":")) || !FPackageName::IsValidObjectPath(R.AssetPath) || R.SchemaPath.IsEmpty() || R.SchemaPath.Len()>1024 || R.SchemaPath.Contains(TEXT(":")) || !FPackageName::IsValidObjectPath(R.SchemaPath)) throw std::runtime_error("Schema assignment requires stopped PIE, confirmed /Game database and full schema path"); auto& Registry=FModuleManager::LoadModuleChecked<FAssetRegistryModule>(TEXT("AssetRegistry")).Get(); if(!Registry.GetAssetByObjectPath(FSoftObjectPath(R.AssetPath)).IsValid() || !Registry.GetAssetByObjectPath(FSoftObjectPath(R.SchemaPath)).IsValid()) throw std::runtime_error("Database and schema must exist in registry"); auto* Database=LoadObject<UPoseSearchDatabase>(nullptr,*R.AssetPath); const auto* Schema=LoadObject<UPoseSearchSchema>(nullptr,*R.SchemaPath); if(!IsValid(Database) || Database->HasAnyFlags(RF_Transient) || !IsValid(Schema) || Schema->HasAnyFlags(RF_Transient)) throw std::runtime_error("Persistent native database/schema required"); const FString Before=GetPathNameSafe(Database->Schema); const bool Changed=Database->Schema!=Schema; bool Saved=false;
 if(!R.bDryRun && Changed) { auto* Property=FindFProperty<FProperty>(Database->GetClass(),TEXT("Schema")); if(!Property) throw std::runtime_error("Native schema property unavailable"); FScopedTransaction Transaction(FText::FromString(TEXT("MCP Assign Pose Search Schema"))); Database->Modify(); Database->Schema=Schema; FPropertyChangedEvent Event(Property,EPropertyChangeType::ValueSet); Database->PostEditChangeProperty(Event); if(Database->Schema!=Schema) throw std::runtime_error("Native schema assignment readback mismatch; inspect undo transaction"); Database->MarkPackageDirty(); }
 if(!R.bDryRun && R.bSave) { Saved=GEditor->GetEditorSubsystem<UEditorAssetSubsystem>()->SaveLoadedAsset(Database,false); if(!Saved) throw std::runtime_error("Schema assigned but database save failed"); } FString Result; auto J=TJsonWriterFactory<>::Create(&Result); J->WriteObjectStart(); J->WriteValue(TEXT("asset_path"),R.AssetPath); J->WriteValue(TEXT("before_schema"),Before); J->WriteValue(TEXT("requested_schema"),R.SchemaPath); J->WriteValue(TEXT("current_schema"),GetPathNameSafe(Database->Schema)); J->WriteValue(TEXT("would_change"),Changed); J->WriteValue(TEXT("dry_run"),R.bDryRun); J->WriteValue(TEXT("saved"),Saved); J->WriteValue(TEXT("scope"),TEXT("Native database schema property assignment/change notification. Existing animation compatibility and derived index readiness not established; native listeners may request index work. Clearing unsupported; no explicit index build/search requested.")); J->WriteObjectEnd(); J->Close(); return Result;
}

