 if(!R.bDryRun && R.bSave) { Saved=GEditor->GetEditorSubsystem<UEditorAssetSubsystem>()->SaveLoadedAsset(Schema,false); if(!Saved) throw std::runtime_error("Channel duplicated but schema save failed"); } FString Result; auto J=TJsonWriterFactory<>::Create(&Result); J->WriteObjectStart(); J->WriteValue(TEXT("asset_path"),R.AssetPath); J->WriteValue(TEXT("source_channel_path"),R.ChannelPath); J->WriteValue(TEXT("expected_index"),Expected); J->WriteValue(TEXT("created_channel_path"),CreatedPath); J->WriteValue(TEXT("dry_run"),R.bDryRun); J->WriteValue(TEXT("duplicated"),!R.bDryRun); J->WriteValue(TEXT("saved"),Saved); J->WriteValue(TEXT("scope"),TEXT("Native channel object duplication/append under same schema, then Finalize. Instanced subobjects follow native duplication policy; external references remain shared. Index validity/feature duplication effects not established; no explicit index build/search.")); J->WriteObjectEnd(); J->Close(); return Result;
