  FScopedTransaction Transaction(FText::FromString(TEXT("MCP Pose Search Permutations"))); Schema->Modify(); if(Integer) Property->SetIntPropertyValue(Property->ContainerPtrToValuePtr<void>(Schema),static_cast<uint64>(Requested)); else Property->SetFloatingPointPropertyValue(Property->ContainerPtrToValuePtr<void>(Schema),Requested);
